static void qca8k_port_bridge_leave ( struct dsa_switch * ds , int port , struct net_device * br ) { struct qca8k_priv * priv = ( qca8k_priv * ) ds -> priv ; int i ; for ( i = 1 ; i < QCA8K_NUM_PORTS ; i ++ ) { if ( ds -> ports [ i ] . bridge_dev != br ) { continue ; } qca8k_reg_clear ( priv , QCA8K_PORT_LOOKUP_CTRL ( i ) , BIT ( port ) ) ; } qca8k_rmw ( priv , QCA8K_PORT_LOOKUP_CTRL ( port ) , QCA8K_PORT_LOOKUP_MEMBER , BIT ( QCA8K_CPU_PORT ) ) ; } 